def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    high_pressure_count = 0
    weak_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) <= DAILY_SALARY * 0.6 or opp.get('hp', 0) <= 2:
                weak_count += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(bid)
                if bid >= 80:
                    high_pressure_count += 1

    if not alive_opponents:
        return min(budget, 18.0)

    slots = max(1, int(supply // WATER_REQ))
    alive_count = len(alive_opponents) + 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    second_prev = 0.0
    if len(prev_bids) >= 2:
        sorted_bids = sorted(prev_bids, reverse=True)
        second_prev = sorted_bids[int(1)]
    elif len(prev_bids) == 1:
        second_prev = prev_bids[int(0)]

    urgent = hp <= 3 or no_water_days >= 1
    critical = hp <= 2 or no_water_days >= 2
    abundant = supply >= 24
    tight = supply <= 17

    base = 28.0

    if critical:
        base = 92.0
    elif urgent:
        base = 62.0
    elif abundant:
        base = 24.0
    elif tight:
        base = 38.0

    if slots >= 2:
        base -= 6.0
    else:
        base += 6.0

    if alive_count <= slots:
        base = min(base, 16.0)

    if high_pressure_count >= slots and not urgent:
        base = min(base, 22.0)

    if highest_prev >= 110:
        if critical:
            base = max(base, 96.0)
        elif urgent:
            base = max(base, 72.0)
        else:
            base = min(base, 20.0)
    elif highest_prev >= 80:
        if urgent:
            base = max(base, second_prev + 3.0, 60.0)
        else:
            base = min(base, 24.0)
    elif highest_prev > 0:
        if slots >= 2 or abundant:
            base = max(base, min(highest_prev + 2.0, 58.0))
        else:
            base = max(base, min(highest_prev + 4.0, 68.0))

    if weak_count >= 2 and not urgent:
        base -= 4.0

    if day >= 8 and budget > 0:
        base += 6.0

    spend_cap = budget
    if not urgent:
        spend_cap = min(spend_cap, DAILY_SALARY * 0.85)
    elif not critical:
        spend_cap = min(spend_cap, DAILY_SALARY * 1.15)

    bid = max(0.0, min(base, spend_cap))

    if budget < 25:
        bid = min(bid, budget)

    return float(max(0.0, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace for immediate reaction.
    prev_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Base aggressiveness depends on our hp and water stress.
    if hp <= 2 or no_water_days >= 2:
        base = DAILY_SALARY * 0.9
    elif hp <= 4:
        base = DAILY_SALARY * 0.75
    else:
        base = DAILY_SALARY * 0.55

    # If someone was bidding high yesterday, slightly undercut to capture allocation.
    if prev_bids:
        highest = max(prev_bids)
        # Cindy-like pressure: bid high yesterday (>= ~110).
        if highest >= DAILY_SALARY * 0.9:
            target = min(base, highest - 5.0)
            # If our base is already low, still bid enough to compete.
            target = max(target, DAILY_SALARY * 0.45)
        else:
            # Otherwise, bid near the top but not max.
            target = max(base, min(budget, max(prev_bids) * 0.95))

    else:
        target = base

    # Adjust for supply: higher supply allows lower bid to secure enough water.
    # supply in [15,25]
    if supply >= 22:
        target *= 0.9
    elif supply <= 16:
        target *= 1.05

    # Final clamp: cannot exceed budget; also keep within reasonable band.
    target = max(0.0, min(budget, target))

    # If supply is very tight relative to our requirement, ensure we don't go too low.
    # (Assume allocation roughly proportional to bid; we keep a floor.)
    if supply < WATER_REQ + 5:
        target = max(target, DAILY_SALARY * 0.5)

    return float(target)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # If no opponents are alive, bid conservatively to ensure survival
    if not alive_opponents:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    # Collect yesterday's bids from active opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Determine the highest bid from yesterday among active opponents
    highest_prev_bid = 0.0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    # --- Bidding Logic ---

    # 1. Survival Mode: If HP is critically low or I missed water yesterday
    if my_status['hp'] <= 2 or my_status['no_water_days'] > 0:
        # Bid very aggressively to survive
        return float(min(my_status['budget'], DAILY_SALARY * 0.95))

    # 2. Late Game Aggression: If it's getting close to the end and I need water
    if day_context['day'] >= EPISODE_DAYS - 3: # Last 3 days
        # In late game, always bid high to secure water, especially if HP isn't perfect
        return float(min(my_status['budget'], DAILY_SALARY * 0.9))

    # 3. Normal Game: Adjust bid based on previous competition
    # Since my WATER_REQ is 13 and supply is 15-25, there's always effectively only 1 "slot" for me, making it competitive.

    # If the highest opponent bid yesterday was very high (Alex/Eric behavior)
    if highest_prev_bid >= DAILY_SALARY * 0.8: 
        if my_status['hp'] > 4: # If my HP is good, I can try to save budget
            # Bid moderately, but still enough to show intent, might lose but save budget
            bid = DAILY_SALARY * 0.5 
            strong_opp_bids = [b for b in yesterday_bids if b >= DAILY_SALARY * 0.7]
            if strong_opp_bids:
                bid = max(bid, max(strong_opp_bids) * 0.9) # Don't completely ignore strong opponents
            return float(min(my_status['budget'], bid))
        else: # HP is not great, need water, bid very high
            return float(min(my_status['budget'], DAILY_SALARY * 0.9))

    # If highest opponent bid was moderate or low
    # Try to win by bidding slightly above the highest previous bid, or a solid base
    bid = max(DAILY_SALARY * 0.55, highest_prev_bid + 2.0) 

    # Ensure bid is within budget and non-negative
    bid = min(my_status['budget'], bid)
    bid = max(0.0, bid)

    # Ensure a minimum bid if budget allows, to stay in the game
    if my_status['budget'] > 0 and bid < DAILY_SALARY * 0.1:
        bid = DAILY_SALARY * 0.1

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if not alive_opponents:
        return 10.0

    avg_prev = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 70.0

    if my_status['hp'] < 4:
        return min(my_status['budget'], DAILY_SALARY * 1.1)

    if supply < 18:
        return min(my_status['budget'], max(avg_prev * 1.05, 82.0))

    return min(my_status['budget'], max(avg_prev * 0.95, 75.0))
